// Package postgres writes audit events to PostgreSQL via jackc/pgx.
// The queries are generated by sqlc from queries.sql.
package postgres

import (
	"context"

	"github.com/jackc/pgx/v5"
	"github.com/jackc/pgx/v5/pgtype"

	"github.com/garamsh/garam/internal/audit"
	"github.com/garamsh/garam/internal/audit/postgres/db"
	"github.com/garamsh/garam/internal/errorx"
	"github.com/garamsh/garam/internal/grn"
	"github.com/garamsh/garam/internal/pgxerr"
	"github.com/garamsh/garam/internal/pgxtype"
)

// RecordSend writes the send event inside tx, the transaction that
// writes the send's outcome, so the event commits exactly when the
// outcome does (ADR-0106). It takes a transaction rather than a pool
// for that reason: an event written beside its outcome rather than
// with it could record a send that never happened.
func RecordSend(ctx context.Context, tx pgx.Tx, s audit.Send) error {
	switch s.Decision() {
	case audit.DecisionAuthorized, audit.DecisionRefused:
	default:
		return errorx.New(errorx.KindInternal, "audit: unknown decision "+string(s.Decision()))
	}
	params := db.RecordSendParams{
		SenderGrn:    s.Sender().String(),
		RecipientGrn: s.Recipient().String(),
		SenderOrg:    grn.Org(s.Sender().Organization).String(),
		RecipientOrg: grn.Org(s.Recipient().Organization).String(),
		Decision:     string(s.Decision()),
	}
	if id, stored, ok := s.Message(); ok {
		params.MessageID = pgtype.Text{String: id, Valid: true}
		params.MessageCreatedAt = pgxtype.Timestamptz(stored)
	}
	return pgxerr.Classify(db.New(tx).RecordSend(ctx, params), "record send", nil, nil)
}
